def greet(name: str) -> str:
    return f"Hello, {name}!"


if __name__ == "__main__":
    print(greet("AutoForge"))

public class Hello {
    public static void main(String[] args) {
        System.out.println("Hello, AutoForge!");
    }
}

package main

import "fmt"

func main() {
    fmt.Println("Hello, AutoForge!")
